{"command": "cd /tmp/sv-a66ca2c2c21e42b7a7a9e917d556bced/advanced-multi-complexity && python3 -c "
import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            tfm = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                key = (name, tfm, pkg['id'])
                result[key] = pkg.get('resolvedVersion', pkg.get('requestedVersion', ''))
    return result

b = extract(baseline)
a = extract(after)

changes = []
unchanged = []
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(key, 'N/A')
    av = a.get(key, 'N/A')
    if bv != av:
        changes.append((key, bv, av))
    else:
        unchanged.append((key, bv))

print('=== CHANGES ===')
for (proj, tfm, pkg), bv, av in changes:
    print(f'{proj} | {tfm} | {pkg} | {bv} -> {av}')

print(f'\n=== UNCHANGED: {len(unchanged)} packages ===')
" 2>/dev/null", "description": "Compare baseline vs after", "initial_wait": 15}

